import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Checklist manuale — embedded search, export, impostazioni (M6-WP6)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m6-search-export.md","filePath":"qa/m6-search-export.md"}'),l={name:"qa/m6-search-export.md"};function r(n,e,c,s,d,m){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="checklist-manuale-—-embedded-search-export-impostazioni-m6-wp6" tabindex="-1">Checklist manuale — embedded search, export, impostazioni (M6-WP6) <a class="header-anchor" href="#checklist-manuale-—-embedded-search-export-impostazioni-m6-wp6" aria-label="Permalink to &quot;Checklist manuale — embedded search, export, impostazioni (M6-WP6)&quot;">​</a></h1><p>Da eseguire con <code>task run-desktop</code> su macOS, Windows e Linux. Segnare <code>[x]</code> con data e sistema operativo. Gli automatismi (vitest, <code>go test</code>) coprono rendering, sanificazione e scrittura; qui si verifica ciò che solo la GUI reale mostra.</p><h2 id="embedded-search" tabindex="-1">Embedded search <a class="header-anchor" href="#embedded-search" aria-label="Permalink to &quot;Embedded search&quot;">​</a></h2><ul><li>[ ] Una nota con un blocco <code>query</code> (es. <code>tag:#todo</code>, <code>sort: modified</code>, <code>limit: 5</code>) mostra in Live Preview l&#39;elenco con conteggio e riga di contesto evidenziata; col cursore dentro il blocco compare il sorgente.</li><li>[ ] Lo stesso blocco in Reading view. <code>view: cards</code> mostra la griglia.</li><li>[ ] Modificare/creare una nota che corrisponde aggiorna l&#39;elenco senza riaprire la nota.</li><li>[ ] Query errata (es. <code>a )</code>): messaggio inline, il resto della nota è intatto.</li><li>[ ] Clic sul titolo apre la nota; clic sulla riga di contesto apre alla riga; &quot;Apri nella ricerca&quot; riempie il pannello.</li><li>[ ] Oltre 100 risultati: &quot;Mostra altri&quot;. La nota ospitante non compare, salvo <code>self: include</code> o impostazione attiva.</li></ul><h2 id="export-html" tabindex="-1">Export HTML <a class="header-anchor" href="#export-html" aria-label="Permalink to &quot;Export HTML&quot;">​</a></h2><ul><li>[ ] &quot;Esporta in HTML&quot;: dialogo nativo, file creato; aprirlo in un browser offline: immagini, callout, codice, math (MathML), Mermaid visibili; tema chiaro/scuro segue il sistema.</li><li>[ ] Nessuna richiesta di rete né script (pannello rete del browser); <code>view-source</code> senza <code>&lt;script&gt;</code>.</li><li>[ ] Immagine &gt; 8 MB: assente dal file e segnalata nel messaggio finale.</li><li>[ ] Scegliere una cartella dentro il vault: rifiutato. Vault condiviso in sola lettura: l&#39;export funziona.</li></ul><h2 id="export-pdf" tabindex="-1">Export PDF <a class="header-anchor" href="#export-pdf" aria-label="Permalink to &quot;Export PDF&quot;">​</a></h2><ul><li>[ ] &quot;Esporta in PDF&quot; apre il dialogo di stampa di sistema; &quot;Salva come PDF&quot; produce un PDF in tema chiaro anche con l&#39;app in tema scuro, senza barre o pannelli, con interruzioni di pagina ragionevoli.</li><li>[ ] macOS: orientamento orizzontale predefinito (limite di <code>WindowPrint</code>), modificabile nel pannello; margini leggibili.</li><li>[ ] Windows (WebView2) e Linux (WebKitGTK): il dialogo si apre e il layer di stampa è corretto; annotare eventuali differenze.</li><li>[ ] Dopo la stampa l&#39;app torna normale (nessun contenuto residuo a schermo).</li></ul><h2 id="impostazioni-file-e-link" tabindex="-1">Impostazioni (File e link) <a class="header-anchor" href="#impostazioni-file-e-link" aria-label="Permalink to &quot;Impostazioni (File e link)&quot;">​</a></h2><ul><li>[ ] &quot;Nuove note&quot;: &quot;accanto alla nota corrente&quot; crea nella cartella della nota attiva.</li><li>[ ] &quot;Allegati&quot;: le tre modalità (cartella / accanto / sottocartella) con incolla di un&#39;immagine.</li><li>[ ] &quot;Conferma prima del cestino&quot; disattivata: nessun dialogo.</li><li>[ ] Chiave bloccata da un profilo: la riga è disabilitata con 🔒.</li></ul>',10)])])}const h=a(l,[["render",r]]);export{p as __pageData,h as default};
